/* Helper: recuperer l'embedding d'un token */
static inline void get_embedding(int token, int16_t output[EMBED_DIM]) {
    if (token < 0 || token >= VOCAB_SIZE) { for(int i=0;i<EMBED_DIM;i++) output[i]=0; return; }
    for (int i = 0; i < EMBED_DIM; i++) output[i] = embedding_table[token * EMBED_DIM + i];
}

